const info = document.querySelector("#info");
const list = document.querySelector("#list");

async function loadCities() {
  const res = await fetch("/demo-api/cities");
  const cities = await res.json();
  for (const city of cities) {
    const li = document.createElement("li");
    li.textContent = `${city.name}: ${city.temp}°C`;
    list.append(li);
  }
  info.textContent = `${cities.length} cities arrived.`;
}

loadCities();

const info = document.querySelector("#info");

async function load(url) {
  info.textContent = "Loading...";
  try {
    const res = await fetch(url);
    if (!res.ok) {
      info.textContent = `Error! Status code: ${res.status}`;
      return;
    }
    const posts = await res.json();
    info.textContent = `Success: ${posts.length} posts arrived.`;
  } catch (err) {
    info.textContent = "Couldn't connect.";
  }
}

document.querySelector("#good").addEventListener("click", () => load("/demo-api/posts"));
document.querySelector("#bad").addEventListener("click", () => load("/demo-api/error"));

