const list = document.querySelector("#list");
const info = document.querySelector("#info");

async function loadRegion(region) {
  // request with a query string, clear the list, add the names, write the summary
  const res = await fetch(`/demo-api/cities?region=${encodeURIComponent(region)}`);
  const cities = await res.json();
  list.innerHTML = "";
  for (const city of cities) {
    const li = document.createElement("li");
    li.textContent = city.name;
    list.append(li);
  }
  info.textContent = `${region}: ${cities.length} cities`;
}

for (const btn of document.querySelectorAll("#regions button")) {
  btn.addEventListener("click", () => loadRegion(btn.dataset.region));
}

