const info = document.querySelector("#info");

async function showHottest(region) {
  // request, find the hottest city, write it
  const res = await fetch(`/demo-api/cities?region=${encodeURIComponent(region)}`);
  const cities = await res.json();
  if (cities.length === 0) {
    info.textContent = "No city found";
    return;
  }
  const hottest = cities.reduce((best, city) => (city.temp > best.temp ? city : best));
  info.textContent = `Hottest: ${hottest.name} (${hottest.temp}°C)`;
}

showHottest("");

