let currentLevel = null;
const info = document.querySelector("#info");

async function loadLevel(n) {
  info.textContent = "Loading...";
  const res = await fetch(`/demo-api/levels/${n}`);
  if (!res.ok) {
    info.textContent = `Level ${n} isn't ready yet.`;
    return;
  }
  const level = await res.json();
  currentLevel = level;
  info.textContent = `Level ${level.level}: ${level.stars} stars, ${level.enemies} enemies, speed ${level.speed}`;
}

for (const btn of document.querySelectorAll("#levels button")) {
  btn.addEventListener("click", () => loadLevel(Number(btn.dataset.level)));
}
